package cpk

import "encoding/binary"

// criXorMask returns a copy of data with the CRI @UTF XOR obfuscation removed.
// The keystream is generated by the standard CRI scheme:
//
//	m = 0x0000655f; t = 0x00004115; out[i] = in[i] ^ (m & 0xff); m = (m * t) & 0xffffffff
//
// The transform is its own inverse, so the same function re-obfuscates data.
func criXorMask(data []byte) []byte {
	out := make([]byte, len(data))
	const (
		seed  = uint32(0x0000655f)
		multi = uint32(0x00004115)
	)
	m := seed
	for i, b := range data {
		out[i] = b ^ byte(m&0xff)
		m = (m * multi) & 0xffffffff
	}
	return out
}

var criLittleEndian = binary.LittleEndian

// Decompress expands a CRILAYLA-compressed payload. The returned slice has the
// size declared in the stream header.
func Decompress(data []byte) ([]byte, error) {
	if len(data) < 0x10 || string(data[:8]) != "CRILAYLA" {
		return nil, errNotCRILAYLA
	}
	usz := criLittleEndian.Uint32(data[8:12])
	hdrOffset := criLittleEndian.Uint32(data[12:16])

	out := make([]byte, int(usz)+0x100)
	start := int(hdrOffset) + 0x10
	if start < 0 || start+0x100 > len(data) {
		return nil, errCRILAYLAHeader
	}
	copy(out[:0x100], data[start:start+0x100])

	if len(data) < 0x100+0x10 {
		return out, nil
	}

	br := &criBitReader{buf: data, pos: len(data) - 0x100 - 1}
	outputEnd := 0x100 + int(usz) - 1
	vleLens := [...]int{2, 3, 5, 8}
	bytesOut := 0

	for bytesOut < int(usz) {
		bit, err := br.get(1)
		if err != nil {
			return nil, err
		}
		if bit != 0 {
			refOffset, err := br.get(13)
			if err != nil {
				return nil, err
			}
			brOff := outputEnd - bytesOut + int(refOffset) + 3
			brLen := 3
			level := 0
			for level < len(vleLens) {
				v, err := br.get(vleLens[level])
				if err != nil {
					return nil, err
				}
				brLen += int(v)
				if v != (1<<vleLens[level])-1 {
					break
				}
				level++
			}
			if level == len(vleLens) {
				for {
					v, err := br.get(8)
					if err != nil {
						return nil, err
					}
					brLen += int(v)
					if v != 255 {
						break
					}
				}
			}
			for i := 0; i < brLen; i++ {
				dst := outputEnd - bytesOut
				if dst < 0x100 || dst >= len(out) {
					return nil, errCRILAYLAOverrun
				}
				if brOff < 0 || brOff >= len(out) {
					return nil, errCRILAYLABackRef
				}
				out[dst] = out[brOff]
				brOff--
				bytesOut++
			}
		} else {
			v, err := br.get(8)
			if err != nil {
				return nil, err
			}
			dst := outputEnd - bytesOut
			if dst < 0x100 || dst >= len(out) {
				return nil, errCRILAYLAOverrun
			}
			out[dst] = byte(v)
			bytesOut++
		}
	}
	return out, nil
}

// criBitReader reads bits from the tail of the compressed payload, walking the
// input backwards while consuming each byte from its high bits down.
type criBitReader struct {
	buf  []byte
	pos  int
	pool byte
	left int
}

func (b *criBitReader) get(n int) (uint32, error) {
	var out uint32
	produced := 0
	for produced < n {
		if b.left == 0 {
			if b.pos < 0 {
				return 0, errCRILAYLATruncated
			}
			b.pool = b.buf[b.pos]
			b.left = 8
			b.pos--
		}
		take := b.left
		if take > n-produced {
			take = n - produced
		}
		out <<= take
		out |= uint32((b.pool >> (b.left - take)) & byte((1<<take)-1))
		b.left -= take
		produced += take
	}
	return out, nil
}
